"""Private Grafana11.6.0 process, ephemeral SQLite and explicit loopback API; no external service."""
import base64,json,os,pathlib,secrets,socket,subprocess,tempfile,time,urllib.error,urllib.request

class PrivateGrafana:
 def __init__(self,prepare=None):self.prepare=prepare;self.process=None;self.log=None
 def __enter__(self):
  self.temp=tempfile.TemporaryDirectory(prefix='of-grafana-');self.root=pathlib.Path(self.temp.name)
  self.user='training_'+secrets.token_hex(4);self.password=secrets.token_hex(24);self.secret=secrets.token_hex(24)
  with socket.socket() as sock:sock.bind(('127.0.0.1',0));self.port=sock.getsockname()[1]
  self.url='http://127.0.0.1:'+str(self.port)
  for name in ('data','logs','plugins','provisioning','cache','dashboards'):(self.root/name).mkdir()
  for name in ('dashboards','datasources','plugins','alerting'):(self.root/'provisioning'/name).mkdir()
  self.config=self.root/'grafana.ini'
  self.config.write_text('[paths]\ndata = '+str(self.root/'data')+'\nlogs = '+str(self.root/'logs')+'\nplugins = '+str(self.root/'plugins')+'\nprovisioning = '+str(self.root/'provisioning')+'\n[server]\nhttp_addr = 127.0.0.1\nhttp_port = '+str(self.port)+'\nroot_url = '+self.url+'/\n[database]\ntype = sqlite3\npath = '+str(self.root/'grafana.db')+'\n[security]\nadmin_user = '+self.user+'\nadmin_password = '+self.password+'\nsecret_key = '+self.secret+'\ndisable_gravatar = true\n[analytics]\nreporting_enabled = false\ncheck_for_updates = false\ncheck_for_plugin_updates = false\n[plugins]\npreinstall_disabled = true\npublic_key_retrieval_disabled = true\npublic_key_retrieval_on_startup = false\nplugin_admin_enabled = false\n[unified_alerting]\nenabled = false\n[log]\nmode = console\nlevel = error\n',encoding='utf8');self.config.chmod(0o600)
  try:
   if self.prepare:self.prepare(self)
   self.start();return self
  except BaseException:self.__exit__(None,None,None);raise
 def start(self):
  assert self.process is None
  version=subprocess.run(['grafana','--version'],capture_output=True,text=True,timeout=8);assert version.returncode==0 and '11.6.0' in version.stdout,version.stdout+version.stderr
  self.log=(self.root/'server.log').open('ab')
  env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'384MiB','XDG_CACHE_HOME':str(self.root/'cache')}
  self.process=subprocess.Popen(['grafana','server','--homepath=/opt/opsforge-grafana','--config='+str(self.config),'--packaging=standalone'],env=env,stdout=self.log,stderr=subprocess.STDOUT)
  deadline=time.monotonic()+50
  while time.monotonic()<deadline:
   assert self.process.poll() is None,'NATIVE_ENVIRONMENT_ERROR: Grafana exited '+self.logs()
   try:
    code,health=self.request('GET','/api/health',authenticate=False)
    if code==200 and health.get('database')=='ok' and health.get('version')=='11.6.0':
     print('NATIVE_GRAFANA_READY:11.6.0-private-sqlite-loopback',flush=True);return
   except (OSError,urllib.error.URLError,ValueError):pass
   time.sleep(.1)
  raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Grafana readiness deadline '+self.logs())
 def request(self,method,path,body=None,authenticate=True):
  assert path.startswith('/') and not path.startswith('//')
  headers={'Content-Type':'application/json'}
  if authenticate:headers['Authorization']='Basic '+base64.b64encode((self.user+':'+self.password).encode()).decode()
  data=json.dumps(body).encode() if body is not None else None;request=urllib.request.Request(self.url+path,data=data,headers=headers,method=method)
  try:
   with urllib.request.urlopen(request,timeout=4) as response:code=response.status;raw=response.read()
  except urllib.error.HTTPError as error:code=error.code;raw=error.read()
  try:return code,json.loads(raw)
  except ValueError:return code,raw.decode(errors='replace')
 def logs(self):return (self.root/'server.log').read_text(errors='replace')[-4500:]
 def stop(self):
  if self.process:
   if self.process.poll() is None:
    self.process.terminate()
    try:self.process.wait(6)
    except subprocess.TimeoutExpired:self.process.kill();self.process.wait(3)
   self.process=None
  if self.log:self.log.close();self.log=None
 def __exit__(self,*args):
  try:self.stop()
  finally:
   if hasattr(self,'temp'):self.temp.cleanup()
